/* Versioned glibc imports need matching interposition versions.
 * Library loading is owned by the patched glibc loader, which preserves
 * the original dlopen caller and translates Debian library paths itself. */
GLIBC_2.17 {
  global:
    kill;
    waitpid;
    clone;
    getpid;
    getppid;
    unshare;
    prctl;
    write;
    read;
    capget;
    capset;
    __xstat;
    __xstat64;
    __fxstatat;
    __fxstatat64;
    forkpty;
    ptsname;
    ptsname_r;
    setmntent;
    fopen;
    fopen64;
    open;
    open64;
    creat;
    creat64;
    openat;
    openat64;
    opendir;
    scandir;
    scandir64;
    sigaction;
    signal;
    setuid;
    setgid;
    seteuid;
    setegid;
    setreuid;
    setregid;
    setresuid;
    setresgid;
    setfsuid;
    setfsgid;
    setgroups;
    execl;
    execle;
    execlp;
    execv;
    execve;
    execveat;
    execvp;
    execvpe;
    posix_spawn;
    posix_spawnp;
    popen;
    pclose;
    access;
    eaccess;
    euidaccess;
    faccessat;
    readlink;
    readlinkat;
    __readlink_chk;
    __readlinkat_chk;
    realpath;
    canonicalize_file_name;
    __realpath_chk;
    waitid;
    bind;
    connect;
    listen;
    close;
    getaddrinfo;
    getifaddrs;
    freeifaddrs;
    unlink;
    unlinkat;
    chmod;
    fchmodat;
    chown;
    lchown;
    setxattr;
    lsetxattr;
    fsetxattr;
    syscall;
    utime;
    utimes;
    lutimes;
    utimensat;
    chroot;
};
GLIBC_2.33 {
  global:
    stat;
    stat64;
    lstat;
    lstat64;
} GLIBC_2.17;
